ids = ["LY-211","LY-212","LY-215","LY-216","LY-217","LY-218","LY-219","LY-220","LY-221","LY-222","LY-227","LY-228","LY-230","LY-231","LY-232","LY-234","LY-235","LY-237","LY-240","LY-241"]
assert set(ids) == set(P.keys()), (set(ids) ^ set(P.keys()))
for cid in ids:
    e = P[cid]
    obj = {"case_id": cid, "prediction_text": e["pred"],
           "basis": trad_line(cid) + "\n" + e["basis"],
           "confidence": e["conf"],
           "trigger": {"changed_main": e["cm"], "reserve_used": e["ru"], "disputed": e["di"], "reason": e["trig_reason"]}}
    with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)
for cid in ids:
    d = json.load(open(os.path.join(OUT, cid + ".json")))
    assert d["case_id"] == cid and d["prediction_text"] and d["basis"] and 0 <= d["confidence"] <= 1
    assert set(d["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}
print("B09 written:", len(ids), ids)
print("changed_main:", sum(P[c]["cm"] for c in ids), "reserve_used:", sum(P[c]["ru"] for c in ids), "disputed:", sum(P[c]["di"] for c in ids))
